css:
.outerLabel {
    width: 480px;
    height: 373px;
}

.row {
    width: 100%;
    float: left;

    /*Override bootstrap css that breaks TNT format*/
    margin-right: 0px !important;
    margin-left: 0px !important;
}

.bordered {
    border: 2px solid #000000;
}

.bordered + .bordered {
    border-top: 0px solid #000000;
}

.bordered > .bordered, .UKcolumn2 > .bordered {
    border-top: 0px solid #000000;
    border-left: 0px solid #000000;
    border-right: 0px solid #000000;
}

.bordered > .bordered:last-child, .UKcolumn2 > .bordered:last-child {
    border-bottom: 0px solid #000000;
}          

.bordered-right {
    height: 100%;
    border-right: 2px solid #000000;
}

.padded2 {
    padding: 2px;
}

.centered {
    text-align: center;
}

.innerLabelheight {
    height: 362px;
}

.firstrowheight {
    text-align: right;
    height: 7px;
}

.secondrowheight, .thirdrowheight {
    height: 123px;
}

.collection, .goods, .services {
    width: 44%;
    float: left;
    overflow: hidden;
}

.Line80 {
    height: 25px;
    line-height: 100%;
    padding-left: 2px;
}

.Line75 {
    height: 21px;
    line-height: 100%;
    padding-left: 2px;
}

.address {
    height: 12px;
    line-height: 80%;
    padding-left: 2px;
}

.custref {
    overflow: hidden;
    border-top: 2px solid #000000;
}

.senderheaderheight {
    height: 11px;
}

.senderheaderrow1 {
    width: 20%;
    float: left;
}

.senderheaderrow2 {
    width: 80%;
    float: left;
}

.contactsrow1 {
    width: 25%;
    float: left;
}

.contactsrow2 {
    width: 75%;
    float: left;
}

.barcode, .delivery {
    width: 55%;
    float: left;
}

.fourthrowheight {
    height : 30px;
}

.specinstructions {
    width: 64%;
    overflow: hidden;
    float: left;
}

.dgsection {
    width: 33%;
    overflow: hidden;
    line-height: 26px;
    float: left;
}

.fifthrowheight {
    height: 81px;
}

.packages {
    width: 24.5%;
    float: left;
    overflow: hidden;
}

.fifthrowmargin {
    margin-left: 2px;
    padding-top: 2px;
}

.TandC {
    width: 29.5%;
    float: left;
    overflow: hidden;
}

.separatorheight {
    height: 10px;
}

.Line70 {
    line-height: 70%;
    padding-left: 2px;
    padding-bottom: 2px;
}

.Line40 {
    line-height: 9px;
    padding-left: 2px;
    padding-bottom: 1px;
}

.Line30 {
    line-height: 6px;
}

font {
    color: black;
}

font.carrierLicence {
    font-family: "courier new";
    font-size: 7pt;
}

font.addressHeader {
    font-weight: bold;
    font-family: "arial";
    font-size: 6pt;
}

font.addressData {
    font-family: "courier new";
    font-size: 8pt;
}

font.addressDatasmall {
    font-family: "courier new";
    font-size: 6pt;
}

font.addressHeaderRec {
    font-weight: bold;
    font-family: "arial";
    font-size: 6pt;
}

font.addressDataRec {
    font-weight: bold;
    font-family: "courier new";
    font-size: 8pt;
}

font.addressHeaderCode {
    font-weight: bold;
    font-family: "arial";
    font-size: 8pt;
    letter-spacing: 0.2cm;
}

font.addressDataWeight {
    font-weight: bold;
    font-family: "courier new";
    font-size: 11pt;
}

font.addressSmallPrint {
    font-family: "courier new";
    font-size: 4pt;
}

img.center {
    display: inline-block;
    margin-bottom: 1px;
    margin-left: auto;
    margin-right: auto;
    margin-top: 1px;
}

div.pagebreak {
    page-break-before: always;
}

font.header {
    font-weight: bold;
    font-family: arial, helvetica "sans-serif";
    font-size: 8pt;
}

font.data {
    font-family: arial, "sans-serif";
    font-size: 8pt;
}

font.smallprint {
    font-family: arial, "sans-serif";
    font-size: 6pt;
}

.padded {
    padding: 1px;
}

.padded-top30 {
    padding-top: 30px;
}

.data {
}

.dataBold {
    font-weight: bold;
}

.deliveryDepot {
    padding-top: 8px;
    font-size: 96px;
}

.deliveryPostcode, .premiumService {
    font-size: xx-large;
    font-weight: bold;
}

.text {
    line-height: 54px;
    font-size: 36pt;
}

.normalService {
    font-size: x-large;
}

.tntTelephone {
    font-size: small;
}

.UKouterlabel  {
    height: 98%;
    width: 550px;
}

.UKinnerlabelheight {
    min-height: 625px;
}

.UKfirstrowheight {
    height: 90px;
}

.UKsecondrowheight {
    height: 130px;
}

.UKthirdrowheight {
    height: 244px;
}

.UKfourthrowheight {
    height: 150px;
}

.UKfifthrowheight {
    height: 115px;
}

.UKcolumn1 {
    width: 50%;
    float: left;
}

.UKcolumn2 {
    width: calc(50% - 8px);
    float: left;
    height: 100%;
}

.UKinnerrowheight {
    height: 31%;
}

.UKlogo {
    width: 62%;
    float: left;
}

.UKphone {
    width: 36%;
    float: left;
}

.label {
    width: 40%;
    float: left;
}

.UKlabel {
    width: 59%;
    float: left;
}
